function logged(value, context) {
  if (context.kind !== 'method') throw new TypeError('only methods');
  return function (...args) {
    console.log(`-> ${String(context.name)}(${args.join(', ')})`);
    const result = value.apply(this, args);
    console.log(`<- ${result}`);
    return result;
  };
}

function retry(times) {                       // decorator factory
  return (value, context) => function (...args) {
    for (let i = 1; ; i++) {
      try { return value.apply(this, args); }
      catch (e) { if (i >= times) throw e; }
    }
  };
}

